messages.text:
The change adds `toJSON` next to `list`, exports it, and switches the main guard to emit JSON when `--json` is in argv. `list`, `formatText`, and the data stay as they are, so the default text output is unchanged. Only `src/list.js` is touched; `package.json` is not.

```diff
diff --git a/src/list.js b/src/list.js
--- a/src/list.js
+++ b/src/list.js
@@ -6,5 +6,6 @@
 ];
 function formatText(task) { return `${task.done ? "[x]" : "[ ]"} ${task.id} ${task.title}`; }
 function list(all) { return all.map(formatText).join("\n"); }
-if (require.main === module) console.log(list(tasks));
-module.exports = { list, formatText };
+function toJSON(all) { return JSON.stringify(all.map(({ id, title, done }) => ({ id, title, done })), null, 2); }
+if (require.main === module) console.log(process.argv.includes('--json') ? toJSON(tasks) : list(tasks));
+module.exports = { list, formatText, toJSON };
```
